create or replace function public.list_staff_branch_access(_staff_id uuid) returns table(branch_id uuid,branch_name text,is_primary boolean,can_sell boolean,can_view_reports boolean,can_manage_inventory boolean,can_manage_customers boolean,can_manage_orders boolean,can_manage_expenses boolean) language sql security definer set search_path=public as $func$ select a.branch_id,b.name,a.is_primary,a.can_sell,a.can_view_reports,a.can_manage_inventory,a.can_manage_customers,a.can_manage_orders,a.can_manage_expenses from public.staff_branch_access a join public.branches b on b.id=a.branch_id where a.staff_id=_staff_id and exists(select 1 from public.staff_accounts s where s.id=_staff_id and private.has_store_role(s.store_id,auth.uid(),array['owner'::public.store_role,'manager'::public.store_role])); $func$; revoke all on function public.list_staff_branch_access(uuid) from public; grant execute on function public.list_staff_branch_access(uuid) to authenticated;
